inp = np.array([[2,3,3,4],[3,0,3,3],[2,3,3,3],[2,2,0,3],[2,3,1,3],[1,3,4,3],[3,3,3,1],[3,3,4,4]])
A = full[:8]
bg=3
mask = inp!=bg
H,W = inp.shape
# manhattan distance to nearest non-bg
dist = np.full(inp.shape, 99)
for i in range(H):
    for j in range(W):
        if mask[i,j]: dist[i,j]=0
        else:
            for a in range(H):
                for b in range(W):
                    if mask[a,b]: dist[i,j]=min(dist[i,j], abs(a-i)+abs(b-j))
print(dist)
# does A relate to dist mirrored/expanded?
print(A[:, :4])
